extern vec2 texelStep;    // 1 screen pixel in texture coords
extern vec4 glowColor;    // RGB + intensity alpha
extern float threshold;   // alpha threshold for silhouette
extern float radiusPx;    // Blur radius
extern vec4 u_frameUV;    // minU, minV, sizeU, sizeV
extern float u_time;      // For pulsing

float sampleA(Image tex, vec2 tc) {
  vec2 uvMin = u_frameUV.xy;
  vec2 uvMax = u_frameUV.xy + u_frameUV.zw;
  vec2 pad = texelStep * 0.5;
  vec2 c = clamp(tc, uvMin + pad, uvMax - pad);
  return Texel(tex, c).a;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float a0 = sampleA(tex, tc);
  // Only draw glow OUTSIDE the sprite.
  if (a0 > threshold) return vec4(0.0);

  float total = 0.0;
  float totalWeight = 0.0;

  // Constant integer loops are portable across the older GLSL compilers
  // still used by a few Windows iGPUs. Avoid float-loop termination here:
  // a driver fault in this promotion-only shader presents as green/black
  // full frames rather than a recoverable LÖVE shader error.
  for (int ring = 1; ring <= 2; ring++) {
    float dist = float(ring) * 0.5;
    // Weight falls off with distance
    float w = 1.0 - (dist * 0.5);

    // Rotate each ring slightly to interleave samples
    float angleOffset = float(ring) * 0.3926991;

    for (int sampleIndex = 0; sampleIndex < 8; sampleIndex++) {
      float angle = float(sampleIndex) * 0.7853982 + angleOffset;
      vec2 dir = vec2(cos(angle), sin(angle));
      total += sampleA(tex, tc + dir * texelStep * radiusPx * dist) * w;
      totalWeight += w;
    }
  }

  // Normalize
  float alpha = total / totalWeight;

  // Soften the curve to make it look like a glow rather than a hard outline
  // smoothstep(min, max, x) -> smooth transition
  // Increased multiplier and adjusted range for higher contrast
  alpha = smoothstep(0.1, 0.9, alpha * 3.0);

  // Subtle pulse
  float pulse = 0.9 + 0.1 * sin(u_time * 3.0);

  return vec4(glowColor.rgb, glowColor.a * alpha * pulse);
}

extern vec2  texelStep;    // 1 screen pixel in texture coords
extern float threshold;    // alpha threshold for silhouette
extern float radiusPx;     // blur radius
extern vec4  u_frameUV;    // minU, minV, sizeU, sizeV
extern float u_time;       // seconds
extern float u_alpha;      // overall glow strength
extern vec2  u_dir;        // drift direction
extern float u_cycle;      // seconds per cycle
extern float u_scale;      // spatial scale
extern float u_colorGain;  // overall color gain
extern float u_saturation; // saturation multiplier
extern float u_mixBP;      // bias towards blue-purple palette

vec3 palette(float x, vec3 a, vec3 b, vec3 c, vec3 d){
  return a + b * cos(6.28318 * (c * x + d));
}

float sampleA(Image tex, vec2 tc) {
  vec2 uvMin = u_frameUV.xy;
  vec2 uvMax = u_frameUV.xy + u_frameUV.zw;
  vec2 pad = texelStep * 0.5;
  vec2 c = clamp(tc, uvMin + pad, uvMax - pad);
  return Texel(tex, c).a;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float a0 = sampleA(tex, tc);
  if (a0 > threshold) return vec4(0.0); // draw only outside silhouette

  float total = 0.0;
  float totalWeight = 0.0;

  // Keep both loop bounds compile-time constants. Some older Intel/AMD
  // GLSL drivers miscompile the former float loops with a computed step,
  // which can corrupt the promotion frame or reset the graphics context.
  // Two staggered 8-sample rings are plenty at this sprite size and cut
  // the fragment cost by more than half.
  for (int ring = 1; ring <= 2; ring++) {
    float dist = float(ring) * 0.5;
    float w = 1.0 - (dist * 0.5);
    float angleOffset = float(ring) * 0.3926991;

    for (int sampleIndex = 0; sampleIndex < 8; sampleIndex++) {
      float angle = float(sampleIndex) * 0.7853982 + angleOffset;
      vec2 dir = vec2(cos(angle), sin(angle));
      total += sampleA(tex, tc + dir * texelStep * radiusPx * dist) * w;
      totalWeight += w;
    }
  }

  float alpha = total / totalWeight;
  // Increase contrast by steepening the smoothstep curve
  // smoothstep(0.1, 0.8, ...) cuts off low values and saturates high values earlier
  alpha = smoothstep(0.1, 0.8, alpha * 3.0);

  // Local UV (0..1 in the current frame) for stable prismatic color.
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);

  float u = dot(tcL, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tcL, ortho) * u_scale;

  vec3 colBP = palette(u,
    vec3(0.55, 0.50, 0.58),
    vec3(0.25, 0.20, 0.28),
    vec3(1.00, 1.00, 1.00),
    vec3(0.10, 0.43, 0.78)
  );
  vec3 colWide = palette(u,
    vec3(0.52), vec3(0.12), vec3(1.0), vec3(0.00, 0.33, 0.66)
  );
  vec3 outRGB = mix(colWide, colBP, clamp(u_mixBP, 0.0, 1.0));

  float Y = dot(outRGB, vec3(0.2126, 0.7152, 0.0722));
  outRGB = mix(vec3(Y), outRGB, max(0.0, u_saturation));
  outRGB *= max(0.0, u_colorGain);

  float pulse = 0.92 + 0.08 * sin(u_time * 2.2);
  float aOut = clamp(u_alpha, 0.0, 1.0) * alpha * pulse;
  return vec4(outRGB, aOut);
}

extern number u_time;
extern number u_alpha;
extern vec2   u_dir;
extern number u_cycle;
extern number u_scale;
extern number u_grainScale;
extern number u_grainAmp;
extern number u_filmFreq;
extern number u_filmAmp;
extern number u_specular;
extern number u_fresnelPow;
extern vec4   u_frameUV;
extern number u_colorGain;
extern number u_saturation;
extern number u_pulseAmp;
extern number u_pulseHz;
extern number u_pulseSharpness;
extern number u_pulseMin;
extern number u_sweepEnable;
extern vec3   u_tintLo;
extern vec3   u_tintHi;
extern vec3   u_sweepLo;
extern vec3   u_sweepHi;

float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc) * color;
  if (base.a <= 0.001) return vec4(0.0);
  float alpha = clamp(u_alpha, 0.0, 1.0) * base.a;
  if (alpha <= 0.0) return vec4(0.0);

  // Pulse multiplier for the base foil only (sweep must stay stable).
  float pulseMul = 1.0;
  float hz = max(0.0, u_pulseHz);
  float amp = clamp(u_pulseAmp, 0.0, 1.0);
  if (hz > 0.0 && amp > 0.0) {
    float s = 0.5 + 0.5 * sin(6.28318 * (u_time * hz));
    float sharp = max(0.5, u_pulseSharpness);
    float shaped = pow(s, sharp);
    float minMul = clamp(u_pulseMin, 0.0, 1.0);
    pulseMul = mix(minMul, 1.0 + amp, shaped);
  }

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);

  // Frame-local UV (stable in spritesheets)
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }

  float u = dot(tcL, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tcL, ortho) * u_scale;

  float grainLine = abs(sin(dot(tcL, ortho) * u_grainScale));
  float grainNoise = hash(tcL * 97.0 + vec2(13.3,7.7));
  float grain = mix(grainLine, grainNoise, 0.25);

  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;

  // Subtle per-grade hue drift between two tints.
  float t = 0.5 + 0.5 * sin(6.28318 * (x * 0.08 + v * 0.03));
  vec3 foil = mix(u_tintLo, u_tintHi, t);

  float band = 0.5 + 0.5 * sin(6.28318 * (u * 0.05 + v * 0.03));
  float fres = pow(0.5 + 0.5 * sin(6.28318 * v * 0.10), max(1.0, u_fresnelPow));
  float spec = u_specular * band * (0.2 + 0.8 * fres) * 0.10;

  float grainMul = 1.0 + u_grainAmp * (grain * 0.15 - 0.03);
  vec3 baseRGB = (foil * grainMul + spec) * pulseMul;

  // Diagonal highlight sweep (match legendary visibility)
  float tSweep = 0.5 + 0.5 * sin(6.28318 * ((u_time / max(u_cycle, 0.001)) * 0.55 + v * 0.22));
  float diag = tcL.x + tcL.y;
  float sweepPos = fract(u_time / max(u_cycle, 0.001)) * 2.0;
  float d = abs(diag - sweepPos);
  d = min(d, abs(diag - (sweepPos + 2.0)));
  d = min(d, abs(diag - (sweepPos - 2.0)));
  float width = 0.22;
  float sweep = 1.0 - smoothstep(0.0, width, d);
  sweep = sweep * sweep;

  float hue = diag * 0.35 + (u_time / max(u_cycle, 0.001)) * 0.9;
  float k = 0.5 + 0.5 * cos(6.28318 * hue);
  float k2 = clamp(k * 0.75 + tSweep * 0.25, 0.0, 1.0);
  vec3 sweepCol = mix(u_sweepLo, u_sweepHi, k2);
  float whiteLift = 0.78 + 0.18 * tSweep;
  sweepCol = mix(sweepCol, vec3(1.0), clamp(whiteLift, 0.0, 0.98));
  sweepCol = clamp(sweepCol * 1.45, 0.0, 1.0);

  float sweepGain = 1.35;
  float w = clamp((0.45 - alpha) / 0.30, 0.0, 1.0);
  float sweepAlphaBoost = mix(1.0, 1.0 / max(alpha, 0.030), w);
  vec3 sweepRGB = sweepCol * sweep * sweepGain * sweepAlphaBoost * 1.60;
  sweepRGB *= clamp(u_sweepEnable, 0.0, 1.0);

  // Apply color controls to base only; keep sweep independent.
  float Y = dot(baseRGB, vec3(0.2126, 0.7152, 0.0722));
  baseRGB = mix(vec3(Y), baseRGB, max(0.0, u_saturation));
  baseRGB *= max(0.0, u_colorGain);
  baseRGB *= 0.82;

  // Desaturate sweep as well if u_saturation is 0 (Time Stop case)
  float sY = dot(sweepRGB, vec3(0.2126, 0.7152, 0.0722));
  sweepRGB = mix(vec3(sY), sweepRGB, max(0.0, u_saturation));

  vec3 outRGB = baseRGB + sweepRGB;
  return vec4(outRGB, alpha);
}

extern number u_time;
extern number u_alpha;
extern vec2   u_dir;
extern number u_cycle;
extern number u_scale;
extern number u_grainScale;
extern number u_grainAmp;
extern number u_filmFreq;
extern number u_filmAmp;
extern number u_specular;
extern number u_fresnelPow;
extern vec4   u_frameUV;
extern number u_colorGain;
extern number u_saturation;
extern number u_mixBP;
extern number u_pulseAmp;
extern number u_pulseHz;
extern number u_pulseSharpness;
extern number u_pulseMin;

vec3 palette(float x, vec3 a, vec3 b, vec3 c, vec3 d){
  return a + b * cos(6.28318 * (c * x + d));
}

float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc) * color;
  if (base.a <= 0.001) return vec4(0.0);
  float alpha = clamp(u_alpha, 0.0, 1.0) * base.a;
  if (alpha <= 0.0) return vec4(0.0);

  // Pulse multiplier for the base foil only.
  // IMPORTANT: do NOT pulse the output alpha under ('add','alphamultiply'),
  // because that would also scale the diagonal sweep (user requested sweep stays stable).
  float pulseMul = 1.0;
  float hz = max(0.0, u_pulseHz);
  float amp = clamp(u_pulseAmp, 0.0, 1.0);
  if (hz > 0.0 && amp > 0.0) {
    float s = 0.5 + 0.5 * sin(6.28318 * (u_time * hz));
    float sharp = max(0.5, u_pulseSharpness);
    float shaped = pow(s, sharp);
    float minMul = clamp(u_pulseMin, 0.0, 1.0);
    pulseMul = mix(minMul, 1.0 + amp, shaped);
  }

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);

  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }

  float u = dot(tcL, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tcL, ortho) * u_scale;

  float grainLine = abs(sin(dot(tcL, ortho) * u_grainScale));
  float grainNoise = hash(tcL * 97.0 + vec2(13.3,7.7));
  float grain = mix(grainLine, grainNoise, 0.25);

  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;

  // Warm metallic foil palettes (gold -> amber). u_mixBP biases towards the brighter/yellower set.
  float tWarm = 0.5 + 0.5 * sin(6.28318 * ((u_time / max(u_cycle, 0.001)) * 0.55 + v * 0.22));
  float warmBias = clamp(u_mixBP + (tWarm - 0.5) * 0.48, 0.0, 1.0);
  float xWarm = x + (tWarm - 0.5) * 0.35;
  float uWarm = u + (tWarm - 0.5) * 0.22;
  vec3 colAmber = palette(xWarm,
    vec3(0.72, 0.46, 0.16),
    vec3(0.20, 0.16, 0.10),
    vec3(1.00, 1.00, 1.00),
    vec3(0.05, 0.08, 0.12)
  );
  vec3 colGold = palette(uWarm,
    vec3(0.80, 0.62, 0.22),
    vec3(0.18, 0.12, 0.06),
    vec3(1.00, 1.00, 1.00),
    vec3(0.00, 0.04, 0.08)
  );
  vec3 foil = mix(colAmber, colGold, warmBias);

  float band = 0.5 + 0.5 * sin(6.28318 * (u * 0.05 + v * 0.03));
  float fres = pow(0.5 + 0.5 * sin(6.28318 * v * 0.10), max(1.0, u_fresnelPow));
  float spec = u_specular * band * (0.2 + 0.8 * fres) * 0.10;

  float grainMul = 1.0 + u_grainAmp * (grain * 0.15 - 0.03);
  vec3 baseRGB = (foil * grainMul + spec) * pulseMul;

  // Diagonal highlight sweep, warm-only.
  float diag = tcL.x + tcL.y;
  float sweepPos = fract(u_time / max(u_cycle, 0.001)) * 2.0;
  float d = abs(diag - sweepPos);
  d = min(d, abs(diag - (sweepPos + 2.0)));
  d = min(d, abs(diag - (sweepPos - 2.0)));
  float width = 0.22;
  float sweep = 1.0 - smoothstep(0.0, width, d);
  sweep = sweep * sweep;
  float hue = diag * 0.35 + (u_time / max(u_cycle, 0.001)) * 0.9;
  float k = 0.5 + 0.5 * cos(6.28318 * hue);
  float k2 = clamp(k * 0.75 + tWarm * 0.25, 0.0, 1.0);
  vec3 sweepCol = mix(vec3(1.0, 0.82, 0.34), vec3(1.0, 0.98, 0.68), k2);
  // Brighter sweep coloration (keep warm tone but significantly more readable)
  float whiteLift = 0.78 + 0.18 * tWarm;
  sweepCol = mix(sweepCol, vec3(1.0), clamp(whiteLift, 0.0, 0.98));
  sweepCol = clamp(sweepCol * 1.45, 0.0, 1.0);
  float sweepGain = 1.35;
  // Under ('add','alphamultiply') the source RGB is multiplied by alpha.
  // Compensate so the sweep stays visible even when overlay alpha is low.
  // Make the sweep less transparent: compensate more aggressively only when alpha is low.
  float w = clamp((0.45 - alpha) / 0.30, 0.0, 1.0);
  float sweepAlphaBoost = mix(1.0, 1.0 / max(alpha, 0.030), w);
  vec3 sweepRGB = sweepCol * sweep * sweepGain * sweepAlphaBoost * 1.60;

  // Apply color controls/dimming to the base foil, but keep the sweep independent
  // so it doesn't get washed out by finalMul/pulse tuning.
  float Y = dot(baseRGB, vec3(0.2126, 0.7152, 0.0722));
  baseRGB = mix(vec3(Y), baseRGB, max(0.0, u_saturation));
  baseRGB *= max(0.0, u_colorGain);
  baseRGB *= 0.82;

  // Desaturate sweep as well if u_saturation is 0 (Time Stop case)
  float sY = dot(sweepRGB, vec3(0.2126, 0.7152, 0.0722));
  sweepRGB = mix(vec3(sY), sweepRGB, max(0.0, u_saturation));

  vec3 outRGB = baseRGB + sweepRGB;
  return vec4(outRGB, alpha);
}

extern number u_time;
extern number u_alpha;
extern number u_cycle;
extern vec4   u_frameUV; // {minU,minV,sizeU,sizeV}
extern vec3   u_tint;    // legendary highlight color
extern number u_width;   // band thickness (in frame-local UV)
extern number u_gain;    // overall strength

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc) * color;
  if (base.a <= 0.001) return vec4(0.0);
  float a = clamp(u_alpha, 0.0, 1.0) * base.a;
  if (a <= 0.0) return vec4(0.0);

  // Local sprite-space UV (0..1 inside the current frame)
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }

  float diag = tcL.x + tcL.y; // 0..2
  float sweepPos = fract(u_time / max(u_cycle, 0.001)) * 2.0;
  float d = abs(diag - sweepPos);
  d = min(d, abs(diag - (sweepPos + 2.0)));
  d = min(d, abs(diag - (sweepPos - 2.0)));
  float width = max(0.001, u_width);
  float sweep = 1.0 - smoothstep(0.0, width, d);
  sweep = sweep * sweep;

  // Match prism sweep behavior under ('add','alphamultiply'):
  // - RGB carries the highlight; alpha stays as the overlay alpha.
  // - Let alphamultiply handle premultiplication.
  float gain = max(0.0, u_gain);
  vec3 outRGB = u_tint * (sweep * gain);
  return vec4(outRGB, a);
}

extern number u_time;
extern number u_alpha;
extern vec2   u_dir;
extern number u_cycle;
extern number u_scale;
extern number u_grainScale;
extern number u_grainAmp;
extern number u_filmFreq;
extern number u_filmAmp;
extern number u_specular;
extern number u_fresnelPow;
extern vec4   u_frameUV;
extern number u_colorGain;
extern number u_saturation;
extern number u_mixBP;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
  float keepAlive = u_time + u_alpha + u_dir.x + u_dir.y
    + u_cycle + u_scale + u_grainScale + u_grainAmp
    + u_filmFreq + u_filmAmp + u_specular + u_fresnelPow
    + dot(u_frameUV, vec4(1.0)) + u_colorGain + u_saturation
    + u_mixBP;
  if (keepAlive < -1.0e20) return color * Texel(tex, tc);
  return vec4(0.0);
}

