vec3 rgb2hsv(vec3 c){
    float maxc = max(c.r, max(c.g, c.b));
    float minc = min(c.r, min(c.g, c.b));
    float delta = maxc - minc;
    float h = 0.0;
    if (delta > 1e-5){
        if (maxc == c.r){ h = mod((c.g - c.b) / delta, 6.0); }
        else if (maxc == c.g){ h = ((c.b - c.r) / delta) + 2.0; }
        else { h = ((c.r - c.g) / delta) + 4.0; }
        h /= 6.0;
        if (h < 0.0) h += 1.0;
    }
    float s = (maxc <= 0.0) ? 0.0 : (delta / maxc);
    float v = maxc;
    return vec3(h,s,v);
}
vec3 hsv2rgb(vec3 h){
    float H = h.x * 6.0;
    float C = h.z * h.y;
    float X = C * (1.0 - abs(mod(H,2.0)-1.0));
    vec3 rgb = vec3(0.0);
    if (0.0 <= H && H < 1.0) rgb = vec3(C,X,0.0);
    else if (1.0 <= H && H < 2.0) rgb = vec3(X,C,0.0);
    else if (2.0 <= H && H < 3.0) rgb = vec3(0.0,C,X);
    else if (3.0 <= H && H < 4.0) rgb = vec3(0.0,X,C);
    else if (4.0 <= H && H < 5.0) rgb = vec3(X,0.0,C);
    else if (5.0 <= H && H < 6.0) rgb = vec3(C,0.0,X);
    float m = h.z - C;
    return rgb + m;
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a < 0.01) return vec4(0.0);

    vec3 rgb = texel.rgb;
    vec3 finalRGB = rgb;

    // 1. Apply Color Swap
    if (u_swapClothesH && distance(rgb, u_srcClothesH) < u_tolerance) {
        finalRGB = u_dstClothesH;
    } else if (distance(rgb, u_srcClothes) < u_tolerance) {
        finalRGB = u_dstClothes;
    } else if (distance(rgb, u_srcShadow) < u_tolerance) {
        finalRGB = u_dstShadow;
    } else if (u_swapCloak && distance(rgb, u_srcCloakH) < u_tolerance) {
        finalRGB = u_dstCloakH;
    } else if (u_swapCloak && distance(rgb, u_srcCloakC) < u_tolerance) {
        finalRGB = u_dstCloakC;
    } else if (u_swapSkin && distance(rgb, u_srcSkinH) < u_tolerance) {
        finalRGB = u_dstSkinH;
    } else if (u_swapSkin && distance(rgb, u_srcSkinC) < u_tolerance) {
        finalRGB = u_dstSkinC;
    } else if (u_swapIron && distance(rgb, u_srcIronH) < u_tolerance) {
        finalRGB = u_dstIronH;
    } else if (u_swapIron && distance(rgb, u_srcIronC) < u_tolerance) {
        finalRGB = u_dstIronC;
    } else if (u_swapIron && distance(rgb, u_srcIronS) < u_tolerance) {
        finalRGB = u_dstIronS;
    }

    // 2. Apply Judgement Tint if active
    if (u_judgementActive) {
        float strength = u_strength * u_weight;
        if (strength > 0.0001) {
            vec3 hsv = rgb2hsv(finalRGB);
            float greenness = clamp(finalRGB.g - max(finalRGB.r, finalRGB.b), 0.0, 1.0);
            float guard = mix(1.0, 1.0 - u_greenGuard, greenness);
            float hueDiff = u_targetHue - hsv.x;
            if (hueDiff > 0.5) hueDiff -= 1.0; else if (hueDiff < -0.5) hueDiff += 1.0;
            hsv.x += hueDiff * u_hueBlend * strength * guard;
            if (hsv.x < 0.0) hsv.x += 1.0; else if (hsv.x > 1.0) hsv.x -= 1.0;
            float diff = u_targetHue - hsv.x;
            if (diff > 0.5) diff -= 1.0; else if (diff < -0.5) diff += 1.0;
            float ad = abs(diff);
            float k = smoothstep(0.12, 0.38, ad);
            float desatAmt = u_desat * strength * k;
            hsv.y = clamp(hsv.y + u_satGain * strength - desatAmt, 0.0, 1.0);
            float preserve = smoothstep(0.0, 1.0, hsv.z);
            float lift = 0.03 * strength * (1.0 - preserve * u_highlightPreserve);
            hsv.z = clamp(mix(hsv.z, 0.6, lift), 0.0, 1.0);
            finalRGB = hsv2rgb(hsv);
            float lumaOut = dot(finalRGB, vec3(0.299, 0.587, 0.114));
            float redLift = u_redBias * strength * smoothstep(0.15, 0.85, 1.0 - lumaOut);
            finalRGB.r = clamp(finalRGB.r + redLift, 0.0, 1.0);
            finalRGB = mix(finalRGB, u_fogColor, u_fogAmt * strength);
            finalRGB = mix(finalRGB, finalRGB, 0.06 * strength); // detailMix
        }
    }

    // 3. Apply Poison Tint (Sickly Muddy Green)
    if (u_poisonStrength > 0.001) {
        vec3 sicklyGreen = vec3(0.22, 0.42, 0.08);
        vec3 multiplied = finalRGB * sicklyGreen * 1.5;
        finalRGB = mix(finalRGB, multiplied, u_poisonStrength * 0.85);
        finalRGB.g += u_poisonStrength * 0.06 * (1.0 - u_poisonStrength * 0.5);
    }

    // 4. Apply Chill Tint (Blue Filter)
    if (u_chillStrength > 0.001) {
        vec3 chillColor = vec3(0.1, 0.35, 1.0);
        vec3 tinted = finalRGB * chillColor * 2.1;
        finalRGB = mix(finalRGB, tinted, u_chillStrength * 0.7);
    }

    // 5. Apply Time Stop Grayscale
    float tsMask = 1.0;
    if (u_ts_active) {
        float dist = distance(sc, u_ts_center);
        float edge = smoothstep(u_ts_radius, u_ts_radius + u_ts_softness, dist);
        tsMask = 1.0 - edge;
    }
    float grayAmt = u_grayscale * tsMask;
    if (grayAmt > 0.001) {
        float gray = dot(finalRGB, vec3(0.299, 0.587, 0.114));
        finalRGB = mix(finalRGB, vec3(gray), grayAmt);
    }

    return vec4(finalRGB, texel.a) * color;
}

extern float u_grayscale;
extern bool u_ts_active;
extern vec2 u_ts_center;
extern float u_ts_radius;
extern float u_ts_softness;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    // Shift red-heavy palette to a natural blue-cyan fire palette
    float luma = (texel.r + texel.g + texel.b) / 3.0;
    vec3 blueFire = vec3(texel.g * 0.4, texel.g * 0.8 + texel.r * 0.2, texel.r * 1.0 + texel.b);
    vec3 res = blueFire * color.rgb;
    float mask = 1.0;
    if (u_ts_active) {
        float dist = distance(sc, u_ts_center);
        float edge = smoothstep(u_ts_radius, u_ts_radius + u_ts_softness, dist);
        mask = 1.0 - edge;
    }
    float grayAmt = u_grayscale * mask;
    if (grayAmt > 0.001) {
        float gray = dot(res, vec3(0.299, 0.587, 0.114));
        res = mix(res, vec3(gray), grayAmt);
    }
    return vec4(res, texel.a * color.a);
}

extern number u_time;
extern vec4 u_quadRect;
extern vec2 u_frameSize;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a <= 0.0) {
        discard;
    }

    vec2 safeQuadSize = max(u_quadRect.zw, vec2(0.000001));
    vec2 safeFrameSize = max(u_frameSize, vec2(1.0));
    vec2 localUV = clamp(
        (tc - u_quadRect.xy) / safeQuadSize,
        vec2(0.0), vec2(0.999999));
    vec2 pixel = floor(localUV * safeFrameSize);
    vec2 onePixel = safeQuadSize / safeFrameSize;
    vec2 sampleMin = u_quadRect.xy + onePixel * 0.5;
    vec2 sampleMax = u_quadRect.xy + safeQuadSize - onePixel * 0.5;

    float neighborAlpha = 1.0;
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc + vec2(onePixel.x, 0.0), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc - vec2(onePixel.x, 0.0), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc + vec2(0.0, onePixel.y), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc - vec2(0.0, onePixel.y), sampleMin, sampleMax)).a);

    vec3 original = texel.rgb * color.rgb;
    vec3 heartPink = vec3(1.00, 0.10, 0.42);
    vec3 blush = vec3(1.00, 0.82, 0.89);

    // Keep the source palette. Two quick blush pulses cover only the
    // source sprite's opaque pixels; there is no frame-positioned mask
    // that could flicker on an isolated head/weapon pixel.
    float cycle = mod(u_time, 0.72) / 0.72;
    float firstBeat = 1.0 - smoothstep(0.0, 0.075,
        abs(cycle - 0.14));
    float secondBeat = 1.0 - smoothstep(0.0, 0.065,
        abs(cycle - 0.30));
    float heartbeat = max(firstBeat, secondBeat * 0.72);
    vec3 tempted = mix(original, heartPink,
        0.07 + heartbeat * 0.28);
    tempted = mix(tempted, blush, heartbeat * 0.14);

    float innerEdge = smoothstep(0.04, 0.72,
        max(0.0, texel.a - neighborAlpha));
    tempted = mix(tempted, blush,
        innerEdge * (0.48 + heartbeat * 0.34));
    return vec4(clamp(tempted, 0.0, 1.0), texel.a * color.a);
}

