    vec2 localUV = clamp(
        (tc - u_quadRect.xy) / safeQuadSize,
        vec2(0.0), vec2(0.999999));
    vec2 pixel = floor(localUV * safeFrameSize);
    vec2 onePixel = safeQuadSize / safeFrameSize;
    vec2 sampleMin = u_quadRect.xy + onePixel * 0.5;
    vec2 sampleMax = u_quadRect.xy + safeQuadSize - onePixel * 0.5;

    float neighborAlpha = 1.0;
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc + vec2(onePixel.x, 0.0), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc - vec2(onePixel.x, 0.0), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc + vec2(0.0, onePixel.y), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha,
        Texel(tex, clamp(tc - vec2(0.0, onePixel.y), sampleMin, sampleMax)).a);

    vec3 original = texel.rgb * color.rgb;
    float luminance = dot(original, vec3(0.299, 0.587, 0.114));
    vec3 deepCurse = vec3(0.10, 0.015, 0.16);
    vec3 curseMid = vec3(0.64, 0.07, 0.48);
    vec3 curseHighlight = vec3(1.00, 0.62, 0.16);
    vec3 cursed = mix(deepCurse, curseMid,
        smoothstep(0.03, 0.52, luminance));
    cursed = mix(cursed, curseHighlight,
        smoothstep(0.52, 0.95, luminance));

    // Preserve the source shading underneath a strong hostile palette,
    // then place a crisp gold rim inside the original opaque pixels.
    cursed = mix(cursed, original, 0.10);
    float innerEdge = smoothstep(0.04, 0.72,
        max(0.0, texel.a - neighborAlpha));
    cursed = mix(cursed, curseHighlight, innerEdge * 0.78);

    // A restrained moving curse band changes RGB only. Alpha remains
    // exactly the source sprite alpha, so silhouettes never blur/fade.
    float band = 0.5 + 0.5 * sin(
        u_time * 5.0 + pixel.x * 0.42 - pixel.y * 0.31);
    cursed += vec3(0.10, 0.015, 0.09) * band;
    return vec4(clamp(cursed, 0.0, 1.0), texel.a * color.a);
}

extern number u_progress;
extern number u_facing;
extern vec4 u_quadRect;
extern vec2 u_frameSize;
extern vec3 u_brightStone;
extern vec3 u_darkStone;
extern vec2 u_verticalBounds;

float stoneHash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
float spriteAlpha(Image tex, vec2 uv) {
    if (uv.x < u_quadRect.x || uv.y < u_quadRect.y ||
        uv.x >= u_quadRect.x + u_quadRect.z || uv.y >= u_quadRect.y + u_quadRect.w) return 0.0;
    return Texel(tex, uv).a;
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a <= 0.0) {
        discard;
    }

    vec2 safeQuadSize = max(u_quadRect.zw, vec2(0.000001));
    vec2 localUV = clamp((tc - u_quadRect.xy) / safeQuadSize, vec2(0.0), vec2(0.999999));
    vec2 pixel = floor(localUV * max(u_frameSize, vec2(1.0)));

    // Stone spreads upward in small irregular patches, attached to
    // sprite pixels. The finished mineral surface never crawls/flickers.
    float progress = clamp(u_progress, 0.0, 1.0);
    float jitter = (stoneHash(vec2(floor(pixel.x / 3.0), 5.0)) - 0.5) * 2.5;
    float front = mix(u_verticalBounds.y, u_verticalBounds.x, progress)
        + jitter * 4.0 * progress * (1.0 - progress);
    float stoneMask = smoothstep(front - 0.6, front + 0.6, pixel.y + 0.5);
    if (progress <= 0.0) stoneMask = 0.0;
    if (progress >= 0.999) stoneMask = 1.0;
    vec4 original = texel * color;
    if (stoneMask <= 0.001) return original;

    // Keep faces, clothing folds and equipment readable as carved
    // relief, instead of replacing the whole figure with two flat tones.
    float luma = dot(texel.rgb, vec3(0.299, 0.587, 0.114));
    vec2 texelStep = safeQuadSize / max(u_frameSize, vec2(1.0));
    float litEdge = 1.0 - spriteAlpha(tex, tc - vec2(texelStep.x * u_facing, 0.0));
    float topEdge = 1.0 - spriteAlpha(tex, tc - vec2(0.0, texelStep.y));
    float darkEdge = 1.0 - spriteAlpha(tex, tc + vec2(texelStep.x * u_facing, 0.0));
    float facet = (stoneHash(floor(pixel / 4.0)) - 0.5) * 0.065;
    float grain = (stoneHash(pixel) - 0.5) * 0.025;
    float tone = clamp(0.10 + luma * 0.86 + facet + grain
        + litEdge * 0.12 + topEdge * 0.10 - darkEdge * 0.08, 0.0, 1.0);
    vec3 stone = mix(u_darkStone, u_brightStone, tone);

    // Sparse hairline fractures with a faint raised lip. Avoid masking
    // the darkest authored details (eyes, outlines, armor seams).
    float vein = mod(pixel.x + floor(pixel.y * 0.5) + floor(pixel.y / 7.0), 17.0);
    float fractureArea = step(0.46, stoneHash(vec2(floor(pixel.y / 5.0), 9.0)))
        * smoothstep(0.12, 0.35, luma);
    stone *= 1.0 - (1.0 - step(1.0, vein)) * fractureArea * 0.23;
    stone += vec3(0.045, 0.044, 0.037) * (step(1.0, vein) - step(2.0, vein)) * fractureArea;
    // A muted chalk edge briefly marks the advancing crust, then settles.
    float settling = (1.0 - smoothstep(0.0, 2.0, abs(pixel.y + 0.5 - front)))
        * step(0.001, progress) * (1.0 - step(0.999, progress));
    stone += vec3(0.075, 0.071, 0.055) * settling;
    // Preserve the source sprite alpha exactly; only RGB is replaced.
    return vec4(mix(original.rgb, stone, stoneMask), texel.a * color.a);
}

