vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a < 0.01) {
        discard;
    }

    vec2 safeQuadSize = max(u_quadRect.zw, vec2(0.000001));
    vec2 safeFrameSize = max(u_frameSize, vec2(1.0));
    vec2 localUV = clamp((tc - u_quadRect.xy) / safeQuadSize,
        vec2(0.0), vec2(0.999999));
    vec2 onePixel = safeQuadSize / safeFrameSize;
    vec2 sampleMin = u_quadRect.xy + onePixel * 0.5;
    vec2 sampleMax = u_quadRect.xy + safeQuadSize - onePixel * 0.5;

    // Exact 1-pixel inner silhouette edge
    float neighborAlpha = 1.0;
    neighborAlpha = min(neighborAlpha, Texel(tex, clamp(tc + vec2(onePixel.x, 0.0), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha, Texel(tex, clamp(tc - vec2(onePixel.x, 0.0), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha, Texel(tex, clamp(tc + vec2(0.0, onePixel.y), sampleMin, sampleMax)).a);
    neighborAlpha = min(neighborAlpha, Texel(tex, clamp(tc - vec2(0.0, onePixel.y), sampleMin, sampleMax)).a);
    float isEdge = step(0.15, texel.a - neighborAlpha);

    vec3 orig = texel.rgb * color.rgb;

    // Shield face edge takes glowing cyan / golden kinetic rim
    // In texture UVs, localUV.x < 0.3 is the shield area
    float shieldFactor = smoothstep(0.40, 0.05, localUV.x);
    vec3 shieldEnergyCol = mix(vec3(0.22, 0.74, 0.97), vec3(1.00, 0.95, 0.60), shieldFactor);

    vec3 res = orig;
    if (isEdge > 0.5) {
        res = mix(res, shieldEnergyCol, u_heat * 0.95);
    }

    // Contact impact whiteout flash
    if (u_flash > 0.001) {
        vec3 flashCol = vec3(1.00, 0.98, 0.90);
        res = mix(res, flashCol, u_flash * 0.95);
    }

    return vec4(clamp(res, 0.0, 1.0), texel.a * color.a);
}

