    vec3 darkBronze   = vec3(0.16, 0.09, 0.02);
    vec3 richAmber    = vec3(0.55, 0.30, 0.05);
    vec3 goldYellow   = vec3(0.96, 0.70, 0.12);
    vec3 brightSolar  = vec3(1.00, 0.94, 0.40);
    vec3 pixelWhite   = vec3(1.00, 1.00, 0.90);

    // 1. 2x2 Bayer Dithering Matrix
    vec2 ditherPos = mod(pixel, vec2(2.0));
    float ditherThreshold = 0.50;
    if (ditherPos.x < 1.0 && ditherPos.y < 1.0) ditherThreshold = 0.25;
    else if (ditherPos.x >= 1.0 && ditherPos.y < 1.0) ditherThreshold = 0.75;
    else if (ditherPos.x < 1.0 && ditherPos.y >= 1.0) ditherThreshold = 1.00;
    else ditherThreshold = 0.50;

    // 2. Discrete 2-Row Pixel Wave Scrolling Downward
    float stepY = floor(localUV.y * safeFrameSize.y);
    float waveStep = mod(stepY - floor(u_time * 8.0), 10.0);
    float isWaveRow = step(waveStep, 1.5);

    // Tone mapping with pixel dithering
    vec3 ditherColor = (ditherThreshold < (0.60 * u_strength)) ? goldYellow : richAmber;
    vec3 res = mix(orig, ditherColor, u_strength * 0.45);

    // Wave highlight row
    res = mix(res, brightSolar, isWaveRow * u_strength * 0.45);

    // 3. Crisp 1px Silhouette Golden Rim
    float rimBlink = step(0.35, fract(u_time * 3.5 + pixel.y * 0.15));
    vec3 rimCol = mix(goldYellow, brightSolar, rimBlink);
    res = mix(res, rimCol, isEdge * u_strength * 0.95);

    // 4. Chunky 1-Pixel Micro Sparkles
    float starRnd = hash(pixel + vec2(43.17, 89.61));
    if (starRnd > 0.94) {
        float starBlink = step(0.40, fract(u_time * 6.0 + starRnd * 10.0));
        res = mix(res, pixelWhite, starBlink * u_strength * 0.80);
    }

    // 5. Singularity Impact Flash (u_flash)
    if (u_flash > 0.001) {
        vec3 flashCol = mix(brightSolar, pixelWhite, 0.70);
        res = mix(res, flashCol, u_flash * 0.95);
    }

    return vec4(clamp(res, 0.0, 1.0), texel.a * color.a);
}

extern number u_time;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a < 0.05) {
        discard;
    }

    float blink = step(0.46, fract(u_time * 14.0));
    float pulse = 0.26 + blink * 0.54;
    return vec4(1.0, 1.0, 1.0, texel.a * pulse) * color;
}

extern number u_time;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a < 0.01) return vec4(0.0);

    vec3 bindCore = vec3(0.78, 0.34, 1.00);
    vec3 bindViolet = vec3(0.48, 0.16, 0.92);
    vec3 bindLight = vec3(0.96, 0.70, 1.00);
    float pulse = 0.72 + 0.28 * sin(u_time * 6.0);

    float band1 = 1.0 - smoothstep(0.028, 0.070, abs(sin((tc.y + tc.x * 0.22) * 18.0 - u_time * 3.0)));
    float band2 = 1.0 - smoothstep(0.030, 0.074, abs(sin((tc.y - tc.x * 0.24) * 15.0 + u_time * 2.4)));
    float cross = max(band1, band2 * 0.75);

    float lock = smoothstep(0.50, 0.92, cross);
    vec3 tint = mix(texel.rgb, bindViolet, 0.30 * pulse);
    tint = mix(tint, bindCore, lock * 0.82);

    float edgeLine = smoothstep(0.70, 1.0, cross);
    tint += bindCore * edgeLine * 0.62 * pulse;
    tint += bindLight * edgeLine * 0.30;

    return vec4(tint, texel.a) * color;
}

extern number u_time;
extern number u_slowStrength;
extern vec3 u_slowColor;
extern vec3 u_slowEdgeColor;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    if (texel.a < 0.01) return vec4(0.0);

    vec3 slowColor = u_slowColor;

    // Pulse the background intensity for breathing effect
    float pulse = 0.5 + 0.5 * sin(u_time * 2.5);

    // A slow-moving horizontal heavy gravity wave scrolling down the unit (friction)
    float wave = sin(tc.y * 12.0 + u_time * 2.2);
    wave = smoothstep(-0.4, 0.4, wave); // high-contrast sluggish bands

    // Mix rich bronze fatigue tint into the unit's color (45% mix for good visibility)
    vec3 tinted = mix(texel.rgb, slowColor, 0.45 * u_slowStrength * (0.65 + 0.35 * pulse));

    // Heavy dark sluggish bands (darkening/shadowing effect)
    tinted = mix(tinted, tinted * 0.30, u_slowStrength * 0.60 * wave);

    // Add a subtle glowing friction highlight along the scrolling edge (perfect middle ground!)
    float edge = sin(tc.y * 12.0 + u_time * 2.2 - 0.22);
    edge = smoothstep(0.85, 1.0, edge); // thin elegant glow line
    tinted += u_slowEdgeColor * edge * 0.35 * u_slowStrength;

    return vec4(tinted, texel.a) * color;
}

extern float u_strength;
extern bool u_ts_active;
extern vec2 u_ts_center;
extern float u_ts_radius;
extern float u_ts_softness;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    // standard luminance weights
    float gray = dot(texel.rgb, vec3(0.299, 0.587, 0.114));
    float mask = 1.0;
    if (u_ts_active) {
        float dist = distance(sc, u_ts_center);
        float edge = smoothstep(u_ts_radius, u_ts_radius + u_ts_softness, dist);
        mask = 1.0 - edge;
    }
    vec3 res = mix(texel.rgb, vec3(gray), u_strength * mask);
    return vec4(res * color.rgb, texel.a * color.a);
}

extern vec2 texelStep;
extern vec4 outlineColor;
extern float threshold;
extern float radiusPx;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    float a0 = Texel(tex, tc).a;
    if (a0 <= threshold) {
        vec2 s = texelStep;
        float aL = Texel(tex, tc + vec2(-s.x, 0.0)).a;
        float aR = Texel(tex, tc + vec2( s.x, 0.0)).a;
        float aU = Texel(tex, tc + vec2(0.0, -s.y)).a;
        float aD = Texel(tex, tc + vec2(0.0,  s.y)).a;

        if (max(max(aL, aR), max(aU, aD)) > threshold) {
            return outlineColor;
        }

        if (radiusPx > 1.0) {
            float extra = radiusPx - 1.0;
            vec2 pos = tc / texelStep;
            vec2 f = fract(pos);
            float aLL = Texel(tex, tc + vec2(-s.x * 2.0, 0.0)).a;
            if (aLL > threshold && f.x < extra) return outlineColor;
            float aRR = Texel(tex, tc + vec2( s.x * 2.0, 0.0)).a;
            if (aRR > threshold && f.x > (1.0 - extra)) return outlineColor;
            float aUU = Texel(tex, tc + vec2(0.0, -s.y * 2.0)).a;
            if (aUU > threshold && f.y < extra) return outlineColor;
            float aDD = Texel(tex, tc + vec2(0.0,  s.y * 2.0)).a;
            if (aDD > threshold && f.y > (1.0 - extra)) return outlineColor;
        }
    }
    return vec4(0.0);
}

extern float u_time;
extern float baseAlpha;
extern float pulse;
vec3 rainbow(float x){
    return 0.62 + 0.38 * cos(6.28318 * (x + vec3(0.00, 0.33, 0.67)));
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
    float fade = Texel(tex, tc).a;
    float edgeBand = min(min(tc.x, 1.0 - tc.x), min(tc.y, 1.0 - tc.y));
    float phase = tc.x * 0.90 + tc.y * 0.65 - edgeBand * 4.0 + u_time * 0.16;
    vec3 rgb = mix(rainbow(phase), vec3(1.0), 0.08);
    return vec4(rgb, fade * baseAlpha * pulse) * color;
}

extern vec3 u_tint;
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    vec4 texel = Texel(tex, tc);
    // We want to multiply the background by the tint where the sprite is.
    // Areas with alpha 0 should return white (1,1,1) so the multiplication is neutral.
    vec3 res = mix(vec3(1.0, 1.0, 1.0), u_tint, texel.a);
    return vec4(res, 1.0);
}

extern number u_time;
extern vec3   u_uiBase;
extern vec2   u_dir;
extern number u_cycle;
extern number u_scale;
extern number u_grainScale;
extern number u_grainAmp;
extern number u_filmFreq;
extern number u_filmAmp;
extern number u_specular;
extern number u_fresnelPow;
extern number u_colorGain;
extern number u_saturation;
extern number u_mixBP;

vec3 palette(float x, vec3 a, vec3 b, vec3 c, vec3 d){
  return a + b * cos(6.28318 * (c * x + d));
}
float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc);
  if (base.a <= 0.001) return vec4(0.0);

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);

  float u = dot(tc, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tc, ortho) * u_scale;

  float grainLine = abs(sin(dot(tc, ortho) * u_grainScale));
  float grainNoise = hash(tc * 97.0);
  float grain = mix(grainLine, grainNoise, 0.25);

  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;

  vec3 colBP = palette(x, vec3(0.75, 0.70, 0.78), vec3(0.25, 0.20, 0.28), vec3(1.00, 1.00, 1.00), vec3(0.10, 0.43, 0.78));
  vec3 colWide = palette(u, vec3(0.72), vec3(0.12), vec3(1.0), vec3(0.00, 0.33, 0.66));
  vec3 foil = mix(colWide, colBP, clamp(u_mixBP, 0.0, 1.0));

  float band = 0.5 + 0.5 * sin(6.28318 * (u * 0.05 + v * 0.03));
  float fres = pow(0.5 + 0.5 * sin(6.28318 * v * 0.10), max(1.0, u_fresnelPow));
  float spec = u_specular * band * (0.2 + 0.8 * fres) * 0.15;

  float grainMul = 1.0 + u_grainAmp * (grain * 0.15 - 0.03);
  vec3 outRGB = foil * grainMul + spec;

  outRGB = mix(u_uiBase, outRGB, 0.82);

  float Y = dot(outRGB, vec3(0.2126, 0.7152, 0.0722));
  outRGB = mix(vec3(Y), outRGB, max(0.0, u_saturation));

  float luma = dot(base.rgb, vec3(0.299, 0.587, 0.114));
  outRGB *= (luma * u_colorGain * 1.5);

  return vec4(outRGB, base.a) * color;
}

extern vec3 sourceA;
extern vec3 targetA;
extern vec3 sourceB;
extern vec3 targetB;
extern vec3 sourceC;
extern vec3 targetC;
extern float threshold;

vec4 effect(vec4 color, Image tex, vec2 texture_coords, vec2 screen_coords) {
    vec4 texel = Texel(tex, texture_coords);
    if (texel.a > 0.001) {
        if (distance(texel.rgb, sourceA) <= threshold) {
            texel.rgb = targetA;
        } else if (distance(texel.rgb, sourceB) <= threshold) {
            texel.rgb = targetB;
        } else if (distance(texel.rgb, sourceC) <= threshold) {
            texel.rgb = targetC;
        }
    }
    return texel * color;
}

extern vec2 texelStep;
extern vec4 outlineColor;
extern float threshold;
extern float radiusPx;

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc) {
    float a0 = Texel(tex, tc).a;
    if (a0 > threshold) {
        return vec4(0.0);
    }
    float found = 0.0;
    for (int radiusIndex = 1; radiusIndex <= 6; radiusIndex++) {
        float r = float(radiusIndex);
        if (r > radiusPx) { break; }
        vec2 s = texelStep * r;
        float a1 = Texel(tex, tc + vec2( s.x, 0.0)).a;
        float a2 = Texel(tex, tc + vec2(-s.x, 0.0)).a;
        float a3 = Texel(tex, tc + vec2(0.0,  s.y)).a;
        float a4 = Texel(tex, tc + vec2(0.0, -s.y)).a;
        float a5 = Texel(tex, tc + vec2( s.x,  s.y)).a;
        float a6 = Texel(tex, tc + vec2(-s.x, -s.y)).a;
        float a7 = Texel(tex, tc + vec2( s.x, -s.y)).a;
        float a8 = Texel(tex, tc + vec2(-s.x,  s.y)).a;
        float neighbor = max(max(max(a1, a2), max(a3, a4)), max(max(a5, a6), max(a7, a8)));
        if (neighbor > threshold) {
            found = 1.0;
            break;
        }
    }
    if (found <= 0.0) {
        return vec4(0.0);
    }
    return outlineColor;
}
